/* Athlete surfaces share one profile, plan and session history with the existing app. */
(function(root){'use strict';const C=root.IXHUA_CORE,T=root.IXHUA_TRAINING,R=root.IXHUA_RUNNING,E=root.IXHUA_EXERCISES;let ctx;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={runner:'Runner',strength:'Strength & muscle',hybrid:'Hybrid',general:'General fitness',longevity:'Longevity',custom:'Your direction'},domains={running:'Running',strength:'Strength',cardio:'Cardio',mobility:'Mobility',plyo:'Plyometrics',capability:'Capability',overview:'Your program',hybrid:'Hybrid'};
const btn=(text,action,extra='',cls='secondary')=>`<button class="${cls}" data-ix-action="${action}" ${extra}>${text}</button>`;
const S=()=>ctx.state,P=()=>C.normalProfile(S().athlete),commit=fn=>C.transaction(S(),localStorage,ctx.storageKey,fn);
function init(c){ctx=c;}
function order(p=P()){const first=p.primary==='runner'?'running':p.primary==='strength'?'strength':p.primary==='hybrid'?'hybrid':p.primary==='longevity'?'capability':p.primary==='custom'?(({power:'plyo',balance:'capability'})[p.customPriority||p.secondary[0]]||p.customPriority||p.secondary[0]||'overview'):'overview';return [...new Set([first,...(p.primary==='hybrid'&&p.hybridPriority==='running'?['running','strength']:['strength','running']),...(p.primary==='longevity'?['capability']:[]),'cardio','mobility','plyo'])];}
function future(){return (S().trainingPlan||[]).filter(s=>s.status==='planned'&&s.date>=C.dateKey());}
function next(){return future()[0];}
function goalLine(p){if(p.primary==='runner')return R.goalInfo(p).label;if(p.primary==='strength')return p.strength.goal==='muscle'?'Build muscle. Track what changes.':'Strength you can measure.';if(p.primary==='hybrid')return p.hybridPriority==='running'?'Running leads. Strength supports.':p.hybridPriority==='strength'?'Strength leads. Running supports.':'Two ambitions. One training week.';if(p.primary==='longevity')return p.capability.goal||'Keep strength. Keep your possibilities.';if(p.primary==='custom')return p.customGoal||'Train the qualities that matter to you.';return 'A repeatable week. A stronger everyday.';}
function card(s){if(s.type==='running')return root.IXHUA_RUN_UI.card(s);return `<article class="ix-session-card" data-session-type="${s.type}"><div class="ix-session-index">${esc(s.type==='strength'?'S':s.type==='cardio'?'C':s.type==='plyo'?'P':s.type==='capability'?'Q':'M')}</div><div class="ix-session-copy"><span class="label">${esc(humanDate(s.date))} · ${esc(s.time)} · ${esc(s.priority||'PRACTICE')}</span><h3>${esc(s.title)}</h3><p>${Math.round(s.minutes)} min${s.exercises?.length?' · '+s.exercises.length+' movements':''}${s.contacts!=null?' · '+s.contacts+' planned contacts':''}</p></div>${btn('Open','open',`data-id="${s.id}"`)}</article>`;}
function supportItems(s){return (s.support||[]).map((x,i)=>({...x,parentId:s.id,parentTitle:s.title,date:s.date,time:s.time,supportIndex:i}));}
function supportCard(x){const icon=x.type==='mobility'?'🧘':x.type==='plyo'?'⚡':x.type==='cardio'?'🚲':'•';const role=x.role==='prep'?'BEFORE':x.role==='primer'?'BEFORE':x.role==='finisher'?'AFTER':'SUPPORT';return `<article class="ix-session-card ix-support-card" data-session-type="${esc(x.type)}"><div class="ix-session-index">${icon}</div><div class="ix-session-copy"><span class="label">${role} ${esc(x.parentTitle)} · ${Math.round(x.minutes)} MIN</span><h3>${esc(x.title)}</h3><p>${esc(x.reason||'Support work for this session.')}</p></div>${btn('Open block','open-support',`data-id="${x.parentId}" data-support-index="${x.supportIndex}"`)}</article>`;}
function selectedDay(){return S().selectedDate||C.dateKey();}
function humanDate(date,p=P()){return new Date(date+'T12:00:00').toLocaleDateString(p.language||'en',{weekday:'long',month:'short',day:'numeric'}).toUpperCase();}
function compactDate(date,p=P()){return new Date(date+'T12:00:00').toLocaleDateString(p.language||'en',{weekday:'short',day:'numeric'}).toUpperCase().replace(',','');}
function roleFor(date){const sessions=(S().trainingPlan||[]).filter(x=>x.date===date&&x.status==='planned');if(!sessions.length)return 'REST';const key=sessions.find(x=>x.priority==='PRIMARY')||sessions[0];if(key.type==='running')return /interval/i.test(key.title)?'INT':/long/i.test(key.title)?'LONG':/easy|recovery/i.test(key.title)?'EASY':'RUN';if(key.type==='strength')return /lower/i.test(key.title)?'LOWER':/upper/i.test(key.title)?'UPPER':'STR';if(key.type==='plyo')return 'PLYO';if(key.type==='mobility')return 'MOB';if(key.type==='cardio')return 'CARDIO';return String(key.type||'TRAIN').slice(0,6).toUpperCase();}
function weekStrip(date=selectedDay()){const p=P(),start=C.monday(C.dateKey()),days=Array.from({length:21},(_,i)=>C.addDays(start,i));return `<section class="ix-week-carousel" aria-label="Three week training outlook"><div class="ix-week-carousel-head"><b>NEXT 3 WEEKS</b><span>Swipe →</span></div><nav class="ix-week-strip ix-week-strip-21" aria-label="Next three weeks">${days.map((d,i)=>{const active=d===date,today=d===C.dateKey(),complete=(S().trainingPlan||[]).some(x=>x.date===d&&x.status==='completed'),weekStart=i%7===0;return `<button data-ix-action="select-day" data-date="${d}" class="ix-week-day ${active?'is-selected':''} ${today?'is-today':''} ${complete?'is-complete':''} ${weekStart&&i?'is-week-start':''}" aria-current="${active?'date':'false'}"><span>${new Date(d+'T12:00:00').toLocaleDateString(p.language||'en',{weekday:'short'}).toUpperCase()}</span><b>${+d.slice(-2)}</b><small>${complete?'✓ ':''}${esc(roleFor(d))}</small></button>`;}).join('')}</nav></section>`;}
function legacyDay(date){return root.REBUILD_DATA?.days?.find(d=>d.date===date)||null;}
function legacyLifeItems(date){const d=legacyDay(date);if(!d)return [];const skipTraining=t=>{const title=String(t[2]||'');return /Upper Body|Lower Body|Full Body|Run|Bike|Row|Jump Rope|Wrestling|Hike|Mobility|Cooldown|Plyometric|Movement Prep/i.test(title);};return (d.tasks||[]).filter(t=>!skipTraining(t)&&String(t[2]||'').toLowerCase()!=='work').map(t=>({time:t[0],title:t[2],meta:t[3]||'',icon:t[1]||'📅',kind:'life',legacy:true}));}
function parseLegacyWork(date){const d=legacyDay(date);if(!d?.work)return null;const raw=String(d.work).replace(/–/g,'-').trim(),parts=raw.split('-').map(x=>x.trim());if(parts.length!==2)return null;let [start,end]=parts,sm=start.match(/\b(AM|PM)\b/i),em=end.match(/\b(AM|PM)\b/i);if(!sm&&em)start+=' '+em[1].toUpperCase();if(!em&&sm)end+=' '+sm[1].toUpperCase();return {time:start,start,end,title:'Work',meta:`${start}–${end}`,icon:'💼',kind:'life',legacy:true};}
function lifeItems(date){const savedShifts=(S().workShifts||[]).filter(e=>e.date===date).map(e=>({time:e.start,end:e.end,title:'Work',meta:e.end?`${e.start}–${e.end}`:'Work shift',icon:'💼',kind:'life'}));const events=(S().customEvents||[]).filter(e=>e.date===date).map(e=>({time:e.start||e.time,title:e.title||e.category||'Life event',meta:e.note||e.category||'Life',icon:e.icon||'📅',kind:'life'}));const legacyWork=savedShifts.length?[]:[parseLegacyWork(date)].filter(Boolean);const explicitTitles=new Set(events.map(e=>String(e.title).toLowerCase()));const legacy=legacyLifeItems(date).filter(e=>!explicitTitles.has(String(e.title).toLowerCase()));return [...savedShifts,...legacyWork,...legacy,...events];}
function minutesFromTime(value){const raw=String(value||'').trim();if(!raw||/flex/i.test(raw))return 9999;const twelve=raw.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)$/i);if(twelve){let h=+twelve[1]%12,m=+(twelve[2]||0);if(twelve[3].toUpperCase()==='PM')h+=12;return h*60+m;}const twentyFour=raw.match(/^(\d{1,2}):(\d{2})$/);if(twentyFour)return +twentyFour[1]*60 + +twentyFour[2];return 9998;}
function timeFromMinutes(value,reference=''){if(!Number.isFinite(value)||value<0)return 'FLEX';const mins=((Math.round(value)%1440)+1440)%1440,h=Math.floor(mins/60),m=mins%60;if(/\b(?:AM|PM)\b/i.test(String(reference))){const ap=h>=12?'PM':'AM',h12=h%12||12;return `${h12}:${String(m).padStart(2,'0')} ${ap}`;}return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;}
function timeline(date){const main=(S().trainingPlan||[]).filter(x=>x.date===date&&x.status==='planned');const sessions=[];for(const x of main){const start=minutesFromTime(x.time),before=(x.support||[]).map((z,i)=>({...z,_supportIndex:i})).filter(z=>z.role==='prep'||z.role==='primer'),after=(x.support||[]).map((z,i)=>({...z,_supportIndex:i})).filter(z=>z.role==='finisher');let cursor=start-before.reduce((a,z)=>a+Math.round(z.minutes),0);for(const z of before){sessions.push({time:timeFromMinutes(cursor,x.time),title:z.title,meta:`${Math.round(z.minutes)} min · ${z.role==='primer'?'power primer':'warm-up'}`,icon:z.type==='plyo'?'⚡':'🧘',kind:'support',id:x.id,supportIndex:z._supportIndex,type:z.type});cursor+=Math.round(z.minutes);}sessions.push({time:x.time,title:x.title,meta:`${Math.round(x.minutes)} min · ${x.priority||'planned'}`,icon:x.type==='running'?'🏃':x.type==='strength'?'🏋️':x.type==='mobility'?'🧘':x.type==='plyo'?'⚡':'❤️',kind:'training',id:x.id,type:x.type});cursor=start+Math.round(x.minutes);for(const z of after){sessions.push({time:timeFromMinutes(cursor,x.time),title:z.title,meta:`${Math.round(z.minutes)} min · easy aerobic finisher`,icon:z.mode==='row'?'🚣':'🚲',kind:'support',id:x.id,supportIndex:z._supportIndex,type:z.type});cursor+=Math.round(z.minutes);}}const items=[...lifeItems(date),...sessions].sort((a,b)=>minutesFromTime(a.time)-minutesFromTime(b.time));return `<section class="ix-today-timeline"><div class="section-head"><h3>Hour by hour</h3><span>Your real day, in order.</span></div>${items.length?items.map(x=>`<div class="ix-timeline-row"><time>${esc(x.time||'FLEX')}</time><div class="ix-timeline-rail"><i></i></div><${x.kind==='training'||x.kind==='support'?'button':'div'} class="ix-timeline-event ${x.kind!=='life'?'is-training':''}" ${x.kind==='training'?`data-ix-action="${x.type==='running'?'open-running':'open'}" data-id="${x.id}"`:x.kind==='support'?`data-ix-action="open-support" data-id="${x.id}" data-support-index="${x.supportIndex}"`:''}><span class="ix-timeline-icon">${x.icon}</span><span><b>${esc(x.title)}</b><small>${esc(x.meta||'')}</small></span>${x.kind!=='life'?'<strong>→</strong>':''}</${x.kind==='training'||x.kind==='support'?'button':'div'}></div>`).join(''):'<div class="ix-empty"><h3>Your day is open.</h3><p>Add work, life events or training in Plan.</p></div>'}</section>`;}
function simpleLongevity(p=P()){return p.primary==='longevity'&&(p.presentation||'simple')==='simple';}
function longevityToday(p,date){const planned=(S().trainingPlan||[]).filter(x=>x.date===date&&x.status==='planned'),main=planned.find(x=>x.priority==='key'||x.priority==='PRIMARY')||planned[0],life=lifeItems(date),nextLife=life[0],emoji=main?.type==='strength'?'🏋️':main?.type==='cardio'?'❤️':main?.type==='capability'?'⚖️':main?.type==='mobility'?'🧘':main?.type==='running'?'🚶':'🌿';return `<div class="ix-longevity-simple">${weekStrip(date)}<div class="ix-human-date">${esc(humanDate(date,p))}<span>IXHUA SIMPLE</span></div><section class="ix-simple-command"><div class="ix-simple-hello">👋 ${date===C.dateKey()?'TODAY':'THIS DAY'}</div><div class="ix-simple-icon">${emoji}</div><h2>${esc(main?.title||'Recovery day')}</h2><p>${main?`About ${Math.round(main.minutes)} minutes${main.time?' · '+esc(main.time):''}`:'No workout is scheduled. Keep the day easy.'}</p>${main?(main.type==='running'?`<button class="primary ix-simple-start" data-ix-action="open-running" data-id="${main.id}">START →</button>`:btn('START →','open',`data-id="${main.id}"`,'primary ix-simple-start')):''}</section>${nextLife?`<section class="ix-simple-next"><span>LATER</span><h3>${esc(nextLife.icon)} ${esc(nextLife.title)}</h3><p>${esc(nextLife.meta||nextLife.time||'')}</p></section>`:''}<section class="ix-simple-week-note"><h3>THIS WEEK</h3><p>Tap a day above. IXHUA will tell you what to do.</p></section>${timeline(date)}</div>`;}
function longevityTraining(p,date){const planned=(S().trainingPlan||[]).filter(x=>x.date===date&&x.status==='planned'),main=planned[0];return `${weekStrip(date)}<div class="ix-human-date">${esc(humanDate(date,p))}<span>TRAINING</span></div><section class="ix-simple-command"><div class="ix-simple-hello">TODAY'S MOVEMENT</div><div class="ix-simple-icon">${main?.type==='strength'?'🏋️':main?.type==='cardio'?'❤️':main?.type==='capability'?'⚖️':main?.type==='mobility'?'🧘':'🌿'}</div><h2>${esc(main?.title||'Rest / easy movement')}</h2><p>${main?`About ${Math.round(main.minutes)} minutes`:'Nothing else to do here today.'}</p>${main?(main.type==='running'?`<button class="primary ix-simple-start" data-ix-action="open-running" data-id="${main.id}">OPEN →</button>`:btn('OPEN →','open',`data-id="${main.id}"`,'primary ix-simple-start')):''}</section>${planned.slice(1).map(s=>`<section class="ix-simple-next"><span>ALSO TODAY</span><h3>${s.type==='strength'?'🏋️':s.type==='cardio'?'❤️':s.type==='capability'?'⚖️':s.type==='mobility'?'🧘':'🌿'} ${esc(s.title)}</h3><p>${Math.round(s.minutes)} minutes</p></section>`).join('')}`;}
function today(){const p=P(),date=selectedDay();if(simpleLongevity(p))return longevityToday(p,date);const isToday=date===C.dateKey(),planned=(S().trainingPlan||[]).filter(x=>x.date===date&&x.status==='planned'),up=planned.find(x=>x.priority==='PRIMARY'||x.priority==='key')||planned[0],completed=S().sessions.filter(x=>x.status==='completed'&&x.date===date),life=lifeItems(date),work=life.find(x=>x.title==='Work'),allCount=planned.length+life.length,doneCount=completed.length+(S().tasks?Object.keys(S().tasks).filter(k=>k.startsWith(date+'|')&&S().tasks[k]).length:0);const focus=planned.length?planned.map(x=>x.title).slice(0,2).join(' + '):'Recovery / open day';return `<div data-today-priority="${p.primary}" class="ix-today">${weekStrip(date)}<div class="ix-human-date ix-human-date-large">${esc(humanDate(date,p))}<span>${esc(names[p.primary])}</span></div><section class="ix-rebuild-today"><div class="ix-rebuild-hero-copy"><div class="label">${isToday?'TODAY':'SELECTED DAY'} / ONE PLAN</div><h2>${esc(focus)}</h2><p>${work?`Work ${esc(work.meta)}. Training is arranged around your actual day.`:'No saved work shift on this day. IXHUA uses the cleanest valid training window.'}</p></div><div class="ix-rebuild-stats"><div><b>${planned.length?'Train':'Recover'}</b><span>MAIN FOCUS</span></div><div><b>${work?'WORK':'OFF'}</b><span>SCHEDULE</span></div><div><b>${doneCount}/${Math.max(1,allCount)}</b><span>DONE</span></div><div><b>${p.presentation==='simple'?'SIMPLE':'DETAIL'}</b><span>VIEW</span></div></div></section>${up?`<div class="ix-next-inline"><span><small>NEXT TRAINING</small><b>${esc(up.time)} · ${esc(up.title)}</b></span>${up.type==='running'?`<button class="secondary" data-ix-action="open-running" data-id="${up.id}">Open →</button>`:btn('Open →','open',`data-id="${up.id}"`)}</div>`:''}${timeline(date)}<section class="ix-today-support"><div class="section-head"><h3>Today at a glance</h3>${btn('Open full Plan','plan','','text-action09')}</div><div class="ix-day-pair"><section><span class="label">TRAINING</span><b>${planned.length}</b><p>${planned.length?planned.map(x=>x.type==='running'?'🏃 '+x.title:x.type==='strength'?'🏋️ '+x.title:'• '+x.title).join(' · '):'No planned session'}</p></section><section><span class="label">LIFE</span><b>${life.length}</b><p>${work?'💼 '+work.meta:life[0]?esc(life[0].title):'Open day'}</p></section></div></section>${p.primary==='hybrid'?goalCards(p):p.primary==='runner'?runnerGoal(p):''}<div class="inline09">${btn('Ask IXHUA','ask')}${btn('Weekly review','weekly')}</div><section class="ix-section">${ctx.recovery()}</section></div>`;}
function goalCards(p){const r=R.goalInfo(p),unit=p.units==='metric'?'kg':'lb',factor=p.units==='metric'?1:2.2046226218;return `<div class="ix-goal-pair"><section><span class="label">RUNNING ${p.hybridPriority==='running'?' / PRIMARY':''}</span><h3>${esc(r.label)}</h3><p>${p.running.targetSeconds?'Target '+C.duration(p.running.targetSeconds):'Build from your measured baseline'}${p.running.benchmarkSeconds?' · Entered benchmark '+C.duration(p.running.benchmarkSeconds):''}</p></section><section><span class="label">STRENGTH ${p.hybridPriority==='strength'?' / PRIMARY':''}</span><h3>${p.strength.targetBenchKg?'Bench '+Math.round(p.strength.targetBenchKg*factor)+' '+unit:p.strength.goal==='muscle'?'Build muscle':'Build strength'}</h3><p>${p.strength.benchKg?'Entered bench benchmark '+Math.round(p.strength.benchKg*factor)+' '+unit:'Your completed sets establish the baseline.'}</p></section></div>`;}
function capabilitySummary(p){const entries=[['Balance',p.capability.balance,'sec'],['Chair stands',p.capability.chairStands,'in 30 sec'],['Comfortable walk',p.capability.walkMinutes,'min']];return `<section class="ix-capability-summary"><div class="label">YOUR ENTERED CAPABILITY BASELINE</div><h3>${esc(p.capability.goal||'Stay capable in the ways you value')}</h3><div class="ix-three-metrics">${entries.map(([k,v,u])=>`<div><b>${v??'—'}</b><span>${k} · ${u}</span></div>`).join('')}</div><p>These are your reported baselines, not a new assessment or wearable reading.</p></section>`;}
function training(){const p=P(),active=S().activeSession,tab=S().trainingTab||order(p)[0],date=selectedDay();if(active)return active.type==='running'?root.IXHUA_RUN_UI.view():activeView();if(simpleLongevity(p))return longevityTraining(p,date);const tabs=`<div class="training-tabs ix-domain-tabs" data-training-priority="${order(p)[0]}">${order(p).map(k=>`<button class="seg-btn ${tab===k?'active':''}" data-tab09="${k}">${domains[k]||k}</button>`).join('')}</div>`;if(tab==='running'){const runs=(S().trainingPlan||[]).filter(s=>s.status==='planned'&&s.type==='running'&&s.date===date);return weekStrip(date)+`<div class="ix-human-date">${esc(humanDate(date,p))}<span>RUNNING</span></div>`+tabs+`<section class="ix-selected-training ix-selected-training-only"><div class="section-head"><h3>${date===C.dateKey()?'TODAY':'SELECTED DAY'}</h3><span>${esc(humanDate(date,p))}</span></div>${runs.length?runs.map(card).join(''):`<div class="ix-empty"><h3>No Running today.</h3><p>Swipe the days above and choose another date.</p></div>`}</section>`;}const isOverview=['hybrid','overview'].includes(tab),all=(S().trainingPlan||[]).filter(s=>s.status==='planned'),mainSelected=all.filter(s=>s.date===date&&(isOverview||s.type===tab)),supportSelected=all.filter(s=>s.date===date).flatMap(s=>supportItems(s)).filter(x=>!isOverview&&x.type===tab);const selected=isOverview?mainSelected:mainSelected;const plyo=tab==='plyo'?T.plyoLevel(p,S().sessions):null;const title=isOverview?goalLine(p):tab==='strength'?(p.strength.goal==='muscle'?'Strength. Built to grow.':'Strength with a purpose.'):tab==='capability'?'Keep the possibilities.':tab==='plyo'?'Power starts with control.':tab==='mobility'?'Warm up. Move better. Train.':'Easy aerobic support.';const body=[...selected.map(card),...supportSelected.map(supportCard)].join('');return weekStrip(date)+`<div class="ix-human-date">${esc(humanDate(date,p))}<span>${esc(names[p.primary])}</span></div>${tabs}<section class="ix-selected-training ix-selected-training-only"><div class="section-head"><h3>${date===C.dateKey()?'TODAY':'SELECTED DAY'}</h3><span>${esc(humanDate(date,p))}</span></div>${body||`<div class="ix-empty"><h3>${isOverview?'Rest / open day':'No '+esc(domains[tab]||tab)+' today.'}</h3><p>Swipe the days above and choose another date.</p></div>`}</section><section class="ix-training-context"><div class="label">${esc(names[p.primary])} / ${isOverview?'ONE PROGRAM':esc(domains[tab]||tab)}</div><h2>${esc(title)}</h2><p>${isOverview?'Only the selected day is shown here. Warm-up, power primers and easy aerobic finishers stay attached to the workout they support.':tab==='mobility'?'Mobility is treated as short preparation before the relevant run or lift, not as a competing hard session.':tab==='plyo'?'Plyometrics are a small quality-first primer when your profile and landing readiness allow them. They are not used as fatigue filler.':tab==='cardio'?'Hybrid strength days can include a short conversational row or bike finisher when it fits the week.':tab==='strength'?`${p.strength.experience} lifting experience · ${p.strength.days} requested days · ${T.architecture(p)} structure`:'Your current profile and available time determine the dose.'}</p></section><div class="inline09">${!plyo||!['off','withheld'].includes(plyo.level)?btn('Start an extra '+(isOverview?'strength session':(domains[tab]||tab).toLowerCase()+' session'),'extra',`data-type="${isOverview?'strength':tab}"`):''}${btn('Exercise library','library','','text-action09')}</div>`;}
function detailsBody(s){return `<div class="label">${esc(humanDate(s.date||C.dateKey()))} · ${s.minutes} MIN · ${esc(domains[s.type]||s.type)}</div><p class="ix-callout">${esc(s.reason||'This session is part of your current IXHUA plan.')}</p>${s.methodology==='COMBAT_HIIT'&&s.protocol?`<section class="ix-support-specific"><div class="label">CONDITIONING INTERVALS</div><h3>${esc(s.protocol.mode)}</h3><p><b>${s.protocol.work}s hard / ${s.protocol.easy}s easy × ${s.protocol.reps}</b> · hard efforts RPE ${s.targetRpe?.join('–')||'8–9'}/10</p><p>5 min progressive warm-up → repeatable intervals → 5 min easy cooldown${s.exercises?.length?' → trunk/core work':''}.</p></section>`:''}${s.omitted?.length?`<p class="ix-note">Equipment cannot cover: ${s.omitted.map(esc).join(', ')}. Add suitable equipment or review the available alternatives.</p>`:''}${(s.exercises||[]).map((e,i)=>`<article class="ix-exercise-preview"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${e.plannedSets||e.sets?.length||1} × ${esc(Array.isArray(e.repRange)?e.repRange.join('–'):e.repRange||'controlled')} ${e.measure==='reps'?'reps':esc(e.measure||'reps')}${e.unilateral?' / side':''} · ${C.duration(e.restSeconds||60)} rest</p></div>${btn('Info','exercise',`data-exercise="${e.id}"`)}</article>`).join('')}${!s.exercises?.length&&s.type==='cardio'?`<div class="ix-support-specific"><h3>${esc(s.title)}</h3><p>${Math.round(s.minutes)} min · conversational Zone 2 · RPE ${Array.isArray(s.targetRpe)?s.targetRpe.join('–'):esc(s.targetRpe||'3–4')}/10</p></div>`:''}${btn('Start '+(domains[s.type]||'workout')+' →','start',`data-id="${s.id}"`,'primary ix-end')}`;}
function supportSession(parent,index){const item=parent?.support?.[+index];if(!item)return null;return {...C.clone(item),id:`${parent.id}::support::${index}`,parentId:parent.id,supportIndex:+index,date:parent.date,time:parent.time,week:parent.week,status:'planned',priority:'support',type:item.type||'mobility',minutes:Math.round(item.minutes||0),exercises:C.clone(item.exercises||[])};}
function supportDetails(parent,index){const s=supportSession(parent,index);if(!s)throw Error('This support block is no longer available.');const icon=s.type==='mobility'?'🧘':s.type==='plyo'?'⚡':s.type==='cardio'?(s.mode==='row'?'🚣':'🚲'):'•';const frequency=s.type==='plyo'?'<p class="ix-note"><b>Frequency:</b> IXHUA keeps plyometric work quality-first. In a Hybrid week it is normally attached to about 1–2 appropriate sessions, not every day. It is withheld or reduced when landing readiness, pain, surface, or session sequencing make it a poor fit.</p>':'';const dose=s.type==='plyo'&&s.contacts!=null?`<div class="ix-contact-dose"><b>${s.contacts}</b><span>planned contacts · ${esc(s.level||'intro')}</span></div>`:'';const cardio=s.type==='cardio'?`<div class="ix-support-specific"><h3>${icon} ${esc(s.title)}</h3><p>${s.minutes} min · conversational Zone 2${Array.isArray(s.targetRpe)?` · RPE ${s.targetRpe.join('–')}/10`:''}</p><p>${esc(s.reason||'Easy aerobic support after the main session.')}</p></div>`:'';const exercises=(s.exercises||[]).map((e,i)=>`<article class="ix-exercise-preview"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${e.plannedSets||1} × ${esc(Array.isArray(e.repRange)?e.repRange.join('–'):e.repRange||'controlled')} ${esc(e.measure||'reps')}${e.unilateral?' / side':''} · ${C.duration(e.restSeconds||45)} rest</p></div>${btn('Info','exercise',`data-exercise="${e.id}"`)}</article>`).join('');ctx.sheet(`${icon} ${s.title}`,`<div class="label">${esc(humanDate(parent.date||C.dateKey()))} · ${esc(domains[s.type]||s.type)} · ${s.minutes} MIN</div><p class="ix-callout">${esc(s.reason||'Support work selected for this session.')}</p>${frequency}${dose}${cardio}${exercises}${btn('Start this block →','start-support',`data-id="${parent.id}" data-support-index="${index}"`,'primary ix-end')}`);}
function open(id){const s=(S().trainingPlan||[]).find(s=>s.id===id)||S().extraSessionPreview;if(!s||s.id!==id)throw Error('This session is no longer available.');ctx.sheet(s.title,detailsBody(s));}
function createActive(s){const p=P();return {...C.clone(s),plannedId:s.id,id:C.id(),status:'active',date:C.dateKey(),startedAt:Date.now(),resumedAt:Date.now(),elapsedMs:0,units:p.units,metrics:{rpe:null,pain:false,landing:null,distanceKm:null},notes:'',rest:null,exercises:(s.exercises||[]).map(e=>({...C.clone(e),sets:Array.from({length:e.plannedSets},()=>({weight:e.loadType==='bodyweight'?'0':'',weightKg:e.loadType==='bodyweight'?0:null,reps:'',rir:'',done:false}))}))};}
function start(id){if(S().activeSession)throw Error('Finish or resume your active session first.');const planned=S().trainingPlan?.find(s=>s.id===id)||S().extraSessionPreview;if(!planned||planned.id!==id||planned.status&&planned.status!=='planned')throw Error('This session is no longer available.');commit(s=>{s.activeSession=createActive(planned);const appt=s.trainingPlan?.find(x=>x.id===id);if(appt)appt.status='active';s.trainingTab=planned.type;s.extraSessionPreview=null;});document.querySelectorAll('dialog').forEach(d=>d.close());ctx.navigate('training');}
function startSupport(id,index){if(S().activeSession)throw Error('Finish or resume your active session first.');const parent=S().trainingPlan?.find(s=>s.id===id);if(!parent)throw Error('This support block is no longer available.');const planned=supportSession(parent,index);if(!planned)throw Error('This support block is no longer available.');commit(s=>{s.activeSession=createActive(planned);s.trainingTab=planned.type;});document.querySelectorAll('dialog').forEach(d=>d.close());ctx.navigate('training');}
function restRemaining(rest){if(!rest)return 0;return rest.paused?rest.remaining:Math.max(0,Math.ceil((rest.endsAt-Date.now())/1000));}
function restPanel(s){const r=s.rest;if(!r)return `<div class="ix-rest-idle"><span>⏱️ REST TIMER</span><b>Starts automatically after a completed set.</b></div>`;return `<div class="ix-rest-live"><div><span>REST ${r.paused?'PAUSED':''}</span><b id="ix-rest-live">${C.duration(restRemaining(r))}</b></div><button data-ix-action="rest-adjust" data-seconds="-15">−15</button><button data-ix-action="rest-toggle">${r.paused?'Resume':'Pause'}</button><button data-ix-action="rest-adjust" data-seconds="15">+15</button><button data-ix-action="rest-reset">Reset</button><button data-ix-action="rest-close" aria-label="Dismiss rest timer">×</button></div>`;}
function activeView(){const s=S().activeSession,unit=s.units==='metric'?'kg':'lb',hasExercises=(s.exercises||[]).length>0,doneCount=(s.exercises||[]).filter(e=>e.sets.every(x=>x.done)).length,rawIndex=hasExercises?s.exercises.findIndex(e=>!e.sets.every(x=>x.done)):-1,currentIndex=hasExercises?(rawIndex<0?s.exercises.length-1:rawIndex):-1,current=currentIndex>=0?s.exercises[currentIndex]:null;return `<section class="ix-active-workout ix-training-mode" data-session-domain="${s.type}"><div class="ix-training-mode-head"><div><span class="label">${s.type==='cardio'?'TIMED BLOCK':'WORKOUT'} · ${s.status==='paused'?'PAUSED':'ACTIVE'}</span><h2>${esc(s.title)}</h2><p>${hasExercises?`Exercise ${Math.min(currentIndex+1,s.exercises.length)} of ${s.exercises.length}${current?' · '+esc(current.name):' · Complete'}`:`${Math.round(s.minutes||0)} min prescribed · ${s.type==='cardio'?'conversational aerobic work':'focused support block'}`}</p></div><div class="ix-workout-clock"><span>WORKOUT</span><b id="ix-session-elapsed">${C.duration(C.elapsed(s)/1000)}</b>${btn(s.status==='paused'?'Resume':'Pause','pause')}</div></div>${hasExercises?`<div class="ix-workout-progress"><i style="width:${s.exercises.length?doneCount/s.exercises.length*100:0}%"></i><span>${doneCount}/${s.exercises.length} exercises complete</span></div>`:''}${restPanel(s)}${s.methodology==='COMBAT_HIIT'&&s.protocol?`<section class="card section ix-conditioning-live"><div class="label">CONDITIONING PRESCRIPTION</div><h3>${esc(s.protocol.mode)}</h3><p><b>${s.protocol.work}s hard / ${s.protocol.easy}s easy × ${s.protocol.reps}</b></p><p class="muted small">Keep hard rounds repeatable. The goal is not to destroy round one and fade.</p></section>`:''}${s.exercises.map((e,i)=>`<article class="ix-working-exercise ${e.sets.every(x=>x.done)?'ix-earned':''} ${i===currentIndex?'is-current':''}"><header><span>${String(i+1).padStart(2,'0')}</span><div><div class="label">${i===currentIndex?'CURRENT · ':''}${esc(e.pattern)}</div><h3>${esc(e.name)}</h3></div>${btn('Info','exercise',`data-exercise="${e.id}"`)}</header><p class="ix-exercise-target">${e.sets.length} sets · ${esc(e.repRange?.join('–')||'controlled')} ${esc(e.measure||'reps')}${e.unilateral?' / side':''} · ${C.duration(e.restSeconds)} rest</p><p class="ix-progression-note">${e.suggestion?.weightKg!=null&&e.suggestion.weightKg>0?`Suggested ${(e.suggestion.weightKg*(s.units==='metric'?1:2.2046226218)).toFixed(1)} ${unit}${e.loadType==='per hand'?' / hand':''}. `:''}${esc(e.suggestion?.reason||'Use controlled repetitions through a comfortable range.')}</p>${!e.sets.some(x=>x.done)?`<div class="ix-rest-inline"><span>⏱️ Rest after each set</span><b>${C.duration(e.restSeconds)}</b></div>`:''}<div class="ix-set-head"><span>SET</span><span>${unit.toUpperCase()}${e.loadType==='per hand'?' / HAND':''}</span><span>${(e.measure||'reps').toUpperCase()}</span><span>${s.type==='strength'?'RIR':'—'}</span><span>DONE</span></div>${e.sets.map((x,j)=>`<div class="ix-set-row ${x.done?'is-done':''}"><b>${j+1}</b><input aria-label="${esc(e.name)} set ${j+1} weight in ${unit}" inputmode="decimal" type="number" min="0" max="1500" step="0.25" data-ix-set="${i},${j},weight" value="${esc(x.weight)}" ${e.loadType==='bodyweight'?'readonly':''}><input aria-label="${esc(e.name)} set ${j+1} ${e.measure||'reps'}" inputmode="numeric" type="number" min="1" max="3600" step="1" data-ix-set="${i},${j},reps" value="${esc(x.reps)}">${s.type==='strength'?`<input aria-label="${esc(e.name)} set ${j+1} reps in reserve" inputmode="numeric" type="number" min="0" max="10" step="1" data-ix-set="${i},${j},rir" value="${esc(x.rir)}">`:'<span>—</span>'}${btn(x.done?'✓':'○','set',`data-pair="${i},${j}" aria-label="Complete ${esc(e.name)} set ${j+1}" aria-pressed="${!!x.done}"`,'ix-done-button')}</div>`).join('')}<div class="inline09">${e.sets.some(x=>!x.done)?btn('Replace exercise','replace',`data-index="${i}"`,'text-action09'):''}${s.type==='strength'?'<small>RIR = clean reps left in reserve.</small>':''}</div></article>`).join('')}<section class="card section"><h3>How did it feel?</h3><div class="form-grid09"><label>Effort (1–10)<input class="field" name="sessionRpe" type="number" min="1" max="10" data-ix-metric="rpe" value="${s.metrics.rpe??''}"></label>${s.type==='cardio'?`<label>Measured distance (${s.units==='metric'?'km':'mi'})<input class="field" type="number" min="0" step="0.01" data-ix-metric="distanceKm" value="${s.metrics.distanceKm==null?'':s.metrics.distanceKm/(s.units==='metric'?1:1.609344)}"></label>`:''}${s.type==='plyo'?`<label>Landing quality<select class="field" data-ix-metric="landing"><option value="">Choose observed quality</option><option value="comfortable" ${s.metrics.landing==='comfortable'?'selected':''}>Quiet and controlled</option><option value="unstable" ${s.metrics.landing==='unstable'?'selected':''}>Unstable / loud contacts</option></select></label>`:''}</div><label class="ix-checkbox"><input type="checkbox" data-ix-metric="pain" ${s.metrics.pain?'checked':''}>Discomfort affected this session</label><label>Session notes<textarea class="field" data-ix-session-notes maxlength="2000">${esc(s.notes)}</textarea></label></section>${btn('End workout →','end','','primary ix-end')}</section>`;}
function stats(s){let sets=0,reps=0,volumeKg=0,contacts=0;for(const e of s.exercises||[]){for(const x of e.sets||[]){if(!x.done)continue;sets++;if((e.measure||'reps')==='reps'){const side=e.unilateral?2:1;reps+=(+x.reps||0)*side;if(s.type==='strength'){const hands=e.loadType==='per hand'&&!/1-Arm/.test(e.name)?2:1;volumeKg+=T.kgOf(x,s)*(+x.reps||0)*hands*side;}}if(s.type==='plyo')contacts+=(e.contactsPerRep||0)*(+x.reps||0);}}return {sets,reps,volumeKg,contacts,exercises:(s.exercises||[]).filter(e=>e.sets?.length&&e.sets.every(x=>x.done)).length};}
function prs(s,history){if(s.type!=='strength')return [];const out=[];for(const e of s.exercises){if(e.measure!=='reps')continue;const ss=e.sets.filter(x=>x.done&&T.kgOf(x,s)>0),old=history.filter(x=>x.status==='completed'&&x.type==='strength').flatMap(session=>(session.exercises||[]).filter(x=>x.name===e.name).flatMap(x=>x.sets.filter(z=>z.done).map(set=>({weightKg:T.kgOf(set,session),reps:+set.reps}))));if(!ss.length||!old.length)continue;const best=Math.max(...ss.map(x=>T.kgOf(x,s))),previous=Math.max(...old.map(x=>x.weightKg));if(best>previous+.001)out.push({exercise:e.name,type:'Weight PR',valueKg:best});}return out;}
function end(){const s=S().activeSession;if(!s||s.type==='running')return;const incomplete=s.exercises.some(e=>e.sets.some(x=>!x.done)),m=ctx.sheet('Save the work you did',`<p>${incomplete?'Some sets are incomplete. Only completed sets count toward your results.':'Review your actual duration before saving.'}</p><form id="ix-finish-session"><label>Actual duration<input class="field" name="duration" inputmode="decimal" value="${C.elapsed(s)>=1000?C.duration(C.elapsed(s)/1000):''}" required placeholder="35.00 → 35:00"></label><p class="ix-form-error" role="alert"></p><button class="primary" type="submit">Save completed workout</button></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();try{const seconds=C.parseDuration(new FormData(e.target).get('duration'));let done;commit(state=>{done=C.clone(state.activeSession);done.elapsedMs=seconds*1000;done.resumedAt=null;done.status='completed';done.endedAt=Date.now();done.rest=null;done.prs=prs(done,state.sessions);state.sessions.push(done);const appt=state.trainingPlan?.find(x=>x.id===done.plannedId);if(appt)appt.status='completed';state.activeSession=null;});m.close();ctx.render();summary(done);}catch(error){m.querySelector('.ix-form-error').textContent=error.message;}};}
function summary(s){const st=stats(s),unit=P().units==='metric'?'kg':'lb',vol=st.volumeKg*(unit==='kg'?1:2.2046226218);ctx.sheet('Workout complete',`<div class="ix-completion-mark">✓</div><div class="label">EARNED / ${esc(domains[s.type])}</div><h3>${esc(s.title)}</h3><div class="ix-three-metrics"><div><b>${C.duration(s.elapsedMs/1000)}</b><span>duration</span></div><div><b>${st.sets}</b><span>completed sets</span></div><div><b>${s.type==='plyo'?st.contacts:s.type==='strength'?Math.round(vol).toLocaleString():st.exercises}</b><span>${s.type==='plyo'?'logged contacts':s.type==='strength'?unit+' × reps':'movements completed'}</span></div></div>${s.prs?.map(r=>`<p class="ix-pr">${esc(r.exercise)} · ${esc(r.type)} · ${(r.valueKg*(unit==='kg'?1:2.2046226218)).toFixed(1)} ${unit}</p>`).join('')||'<p>Your work is saved. Progress grows from repeated sessions.</p>'}<p>${esc(s.notes)}</p><div class="inline09">${btn('View progress','progress','','primary')}${btn('Export summary','export-session',`data-id="${s.id}"`)}</div>`);}
function exercise(id){const e=E.get(id);if(!e)throw Error('Exercise not found.');commit(s=>s.currentExercise={id:e.id,sessionId:s.activeSession?.id||null});ctx.details(e.name);}
function replace(index){const e=S().activeSession?.exercises[index];if(!e)return;const alternatives=E.alternatives(e,P().equipment),m=ctx.sheet('Replace '+e.name,`<p>Alternatives preserve the movement pattern and use your available equipment. Completed work keeps its original exercise identity.</p>${alternatives.map(x=>`<button class="ix-alternative" data-ix-action="choose-alternative" data-index="${index}" data-exercise="${x.id}"><strong>${esc(x.name)}</strong><span>${esc(x.equipment)} · ${esc(x.pattern)}</span></button>`).join('')||'<p>No compatible alternative is available with this equipment. Review equipment in your athlete profile.</p>'}`);}
function plan(){const p=P(),date=selectedDay(),all=S().trainingPlan||[],events=[...(S().workShifts||[]).map(x=>({...x,category:'Work'})),...(S().customEvents||[])],training=all.filter(s=>s.date===date&&s.status!=='cancelled'),life=events.filter(e=>e.date===date),combined=[...training.map(s=>({kind:'training',time:s.time,title:s.title,meta:`${Math.round(s.minutes)} min · ${s.type}`,id:s.id,type:s.type})),...life.map(e=>({kind:'life',time:e.start||e.time,title:e.category||e.title||'Life event',meta:e.end?`${e.start||e.time}–${e.end}`:(e.note||''),event:e}))].sort((a,b)=>minutesFromTime(a.time)-minutesFromTime(b.time));return `<section class="ix-plan ix-plan-mobile" data-plan-priority="${p.primary}"><div class="ix-plan-heading"><div><div class="label">ONE PLAN / ${esc(names[p.primary])}</div><h2>Plan your life + training.</h2></div>${btn('Profile','profile')}</div><p>Swipe through the next three weeks, then edit one day at a time.</p>${weekStrip(date)}<div class="ix-human-date ix-human-date-large">${esc(humanDate(date,p))}<span>PLAN</span></div><section class="ix-plan-day"><div class="section-head"><h3>${date===C.dateKey()?'TODAY':'THIS DAY'}</h3><span>${combined.length} item${combined.length===1?'':'s'}</span></div>${combined.length?combined.map(x=>x.kind==='training'?`<button class="ix-plan-day-row is-training" data-ix-action="${x.type==='running'?'open-running':'open'}" data-id="${x.id}"><time>${esc(x.time)}</time><span><b>${esc(x.title)}</b><small>${esc(x.meta)}</small></span><strong>→</strong></button>`:`<div class="ix-plan-day-row"><time>${esc(x.time||'FLEX')}</time><span><b>${esc(x.title)}</b><small>${esc(x.meta||'Life event')}</small></span></div>`).join(''):`<div class="ix-empty"><h3>Open day.</h3><p>Add a work, school or life event, or let IXHUA place training here.</p></div>`}</section><div class="inline09">${btn('Personalize this week','personalize-week','','primary')}${btn('Add work / school / life event','event')}${btn('Rebuild around my schedule','replan')}</div><section class="ix-life-list"><h3>Your saved commitments</h3>${events.slice().sort((a,b)=>(a.date+(a.start||a.time||'')).localeCompare(b.date+(b.start||b.time||''))).map((e,i)=>`<div class="ix-life-row"><div><b>${esc(e.category||e.title||'Life event')}</b><span>${esc(humanDate(e.date,p))} · ${esc(e.start||e.time)}${e.end?'–'+esc(e.end):''}</span></div>${btn('Remove','remove-event',`data-event="${esc(e.id||'')}" data-index="${i}"`)}</div>`).join('')||'<p>No saved commitments. Add your actual schedule so the planner can protect those windows.</p>'}</section>${(S().planUnplaced||[]).length?`<section class="ix-conflict-summary"><h3>Plan needs attention</h3><p>IXHUA will not silently delete a core goal. Review a corrected plan when a real-life constraint prevents a session from fitting.</p>${btn('Review a corrected plan','replan','','primary')}</section>`:''}</section>`;}
function eventForm(){const m=ctx.sheet('Add a life commitment',`<form id="ix-life-form"><div class="form-grid09"><label>Type<select name="category" class="field"><option>Work</option><option>School</option><option>Life event</option></select></label><label>Name<input name="title" class="field" maxlength="100" placeholder="Optional title"></label><label>Date<input class="field" name="date" type="date" value="${C.dateKey()}" required></label><label>Starts<input class="field" name="start" type="time" value="14:00" required></label><label>Ends<input class="field" name="end" type="time" value="22:00" required></label></div><p>Overnight commitments continue into the next day. Your commute buffer is applied before training is placed.</p><p class="ix-form-error" role="alert"></p><button class="primary" type="submit">Review calendar change</button></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),event={id:C.id(),category:f.get('category'),title:f.get('title')||f.get('category'),date:f.get('date'),start:f.get('start'),end:f.get('end')};if(!C.validDate(event.date)||R.minutesOf(event.start)==null||R.minutesOf(event.end)==null||event.start===event.end)throw Error('Enter a valid date and a start/end time with a nonzero duration.');m.close();reviewPlan(event);}catch(error){m.querySelector('.ix-form-error').textContent=error.message;}};}
function personalizeWeek(options={}){
 const state=S(),p=P(),start=C.monday(selectedDay()),end=C.addDays(start,6),rows=(state.trainingPlan||[]).filter(x=>x.status==='planned'&&x.date>=start&&x.date<=end).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 if(!rows.length)return ctx.notify('There are no planned sessions in this week to personalize.');
 const m=ctx.sheet(options.firstRun?'Review your week before you start':'Personalize this week',`<p>${options.firstRun?'IXHUA built a starting week. Move sessions now if you want; the rest of the app will use exactly the accepted schedule.':'Move the sessions you want. IXHUA keeps the session prescription and updates Today, Training and Plan together.'}</p><p class="ix-note"><b>Guardrails:</b> Upper and Lower must alternate; long/high-demand runs own their day; an easy run up to 45 minutes may share a day with one strength or dedicated conditioning session when starts are at least 3 hours apart.</p><div class="ix-week-editor">${rows.map((x,i)=>`<div class="ix-week-edit-row" data-edit-id="${x.id}"><div><span class="label">${esc(compactDate(x.date,p))}</span><b>${esc(x.title)}</b><small>${Math.round(x.minutes)} min · ${esc(x.type)}</small></div><label>Day<input class="field" type="date" data-edit-date="${i}" value="${x.date}" min="${start}" max="${end}"></label><label>Start<input class="field" type="time" data-edit-time="${i}" value="${x.time}"></label></div>`).join('')}</div><p class="ix-form-error" role="alert"></p><div class="inline09"><button class="primary" id="ix-save-custom-week">${options.firstRun?'Use this week →':'Save my week'}</button>${options.firstRun?'<button class="secondary" id="ix-keep-generated-week">Keep IXHUA week</button>':''}</div>`);
 const err=m.querySelector('.ix-form-error');
 const apply=()=>{
  try{
   const edited=rows.map((x,i)=>({...x,date:m.querySelector(`[data-edit-date="${i}"]`).value,time:m.querySelector(`[data-edit-time="${i}"]`).value}));
   if(edited.some(x=>!x.date||!x.time))throw Error('Every session needs a day and start time.');
   const byDay=new Map();
   edited.forEach(x=>{if(!byDay.has(x.date))byDay.set(x.date,[]);byDay.get(x.date).push(x);});
   for(const [date,day] of byDay){
    const strengths=day.filter(x=>x.type==='strength');
    const runs=day.filter(x=>x.type==='running');
    if(strengths.length>1)throw Error(`${compactDate(date,p)} has two strength sessions. Keep only one strength appointment per day.`);
    if(runs.length>1)throw Error(`${compactDate(date,p)} has two runs. Keep only one run appointment per day.`);
    if(runs.some(x=>x.runKind==='long'||x.stress==='high')&&day.length>1)throw Error(`${compactDate(date,p)} has a long/high-demand run. Give that run its own training day.`);
    if(day.length>1){
      const easy=runs[0],conditioning=day.filter(x=>x.methodology==='COMBAT_HIIT');
      const partner=strengths[0]||conditioning[0];
      if(!(day.length===2&&easy&&easy.runKind==='easy'&&easy.stress==='low'&&easy.minutes<=45&&partner&&(strengths.length===1||conditioning.length===1)))throw Error(`${compactDate(date,p)} can only double an easy run (45 min or less) with one strength or dedicated conditioning session.`);
      if(Math.abs(R.minutesOf(easy.time)-R.minutesOf(partner.time))<180)throw Error(`${compactDate(date,p)} needs at least 3 hours between the easy run and the second session.`);
    }
    const commitments=[...(state.workShifts||[]),...(state.customEvents||[])].filter(e=>e.date===date);
    for(const x of day){const a=R.minutesOf(x.time),b=a+x.minutes;for(const e of commitments){const ea=R.minutesOf(e.start||e.time),eb=e.end?R.minutesOf(e.end):ea+(e.duration||60);if(a<eb&&b>ea)throw Error(`${compactDate(date,p)} ${x.title} overlaps ${e.title||e.category||'a saved commitment'}.`);}}
   }
   const strengths=edited.filter(x=>x.type==='strength'&&T.strengthFamily(x)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
   for(let i=1;i<strengths.length;i++)if(T.strengthFamily(strengths[i])===T.strengthFamily(strengths[i-1]))throw Error(`${strengths[i-1].title} cannot be followed by ${strengths[i].title}. Alternate Upper and Lower.`);
   commit(s=>{const changes=new Map(edited.map(x=>[x.id,x]));s.trainingPlan=(s.trainingPlan||[]).map(x=>changes.has(x.id)?{...x,date:changes.get(x.id).date,time:changes.get(x.id).time,userScheduled:true}:x);s.planUnplaced=(s.planUnplaced||[]).filter(x=>x.week!==start);s.lastPlanChange={type:'user-week-edit',at:Date.now(),week:start};});
   m.close();ctx.render();ctx.notify('Your week is personalized. Today, Training and Plan now use your schedule.');
  }catch(error){err.textContent=error.message;}
 };
 m.querySelector('#ix-save-custom-week').onclick=apply;
 m.querySelector('#ix-keep-generated-week')?.addEventListener('click',()=>{m.close();ctx.render();ctx.notify('IXHUA kept the generated week.');});
}
function reviewPlan(event=null,remove=null){const state=S(),before=C.clone(state.trainingPlan||[]),shifts=C.clone(state.workShifts||[]),life=C.clone(state.customEvents||[]);if(event){if(event.category==='Work')shifts.push(event);else life.push({...event,time:event.start,duration:(R.minutesOf(event.end)-R.minutesOf(event.start)+1440)%1440});}if(remove){const list=remove.index<shifts.length?shifts:life,index=remove.index<shifts.length?remove.index:remove.index-shifts.length;list.splice(index,1);}const gen=T.buildPlan(P(),state.sessions,shifts.concat(life),C.dateKey()),first=gen.sessions[0]?.week,m=ctx.sheet('Review your plan',`<p>${event?'Add '+esc(event.title)+' on '+esc(event.date)+'.':remove?'Remove only this selected commitment.':'Build the next block from your current profile and history.'}</p><div class="ix-plan-comparison"><section><div class="label">CURRENT UPCOMING</div>${before.filter(s=>s.status==='planned'&&s.date>=C.dateKey()).slice(0,5).map(s=>`<p>${esc(compactDate(s.date))} ${s.time}<br><b>${esc(s.title)}</b></p>`).join('')}</section><section><div class="label">PROPOSED</div>${gen.sessions.filter(s=>s.week===first).map(s=>`<p>${esc(compactDate(s.date))} ${s.time}<br><b>${esc(s.title)}</b></p>`).join('')}</section></div><p>Completed workouts stay in history. Unavailable supporting work is explained; missed sessions are not doubled up.</p><button class="primary" id="ix-apply-plan">Apply this change</button><p class="ix-form-error" role="alert"></p>`);const revision=state.revision||0;m.querySelector('#ix-apply-plan').onclick=()=>{try{if((S().revision||0)!==revision)throw Error('Your data changed. Close this proposal and review a fresh one.');commit(s=>{s.lastPlanChange={before,workShifts:C.clone(s.workShifts),customEvents:C.clone(s.customEvents),at:Date.now()};s.workShifts=shifts;s.customEvents=life;s.trainingPlan=before.filter(x=>x.status==='completed'||x.id===s.activeSession?.plannedId).concat(gen.sessions);s.planUnplaced=gen.unplaced;});m.close();ctx.render();ctx.notify('Your calendar and training plan were updated together.');}catch(error){m.querySelector('.ix-form-error').textContent=error.message;}};}
function metric(title,value,note){return `<section class="ix-progress-metric"><span class="label">${title}</span><b>${value}</b><p>${note}</p></section>`;}
function strengthProgress(rows){const p=P(),unit=p.units==='metric'?'kg':'lb',factor=p.units==='metric'?1:2.2046226218,str=rows.filter(s=>s.type==='strength'),volume=str.reduce((a,s)=>a+stats(s).volumeKg,0)*factor;return `<section data-progress-domain="strength"><div class="section-head"><h3>Strength that shows up</h3><span>${p.strength.goal==='muscle'?'Muscle & volume':'Load & consistency'}</span></div><div class="ix-three-metrics">${metric('SESSIONS',str.length,'completed strength sessions')}${metric('VOLUME',Math.round(volume).toLocaleString(),unit+' × completed reps')}${metric('LIFTING DAYS',p.strength.days,'requested per week')}</div>${str.length?ctx.chart(str.map(s=>({date:s.date,value:Math.round(stats(s).volumeKg*factor)})),'Completed strength volume',unit+' × reps'):'<div class="ix-empty">Complete a workout to begin your strength history. No trend is inferred from an entered benchmark.</div>'}${p.strength.targetBenchKg?`<p class="ix-callout">Bench goal: ${(p.strength.targetBenchKg*factor).toFixed(1)} ${unit}. ${p.strength.benchKg?'Entered benchmark: '+(p.strength.benchKg*factor).toFixed(1)+' '+unit+'.':'Log your first bench session to establish a working baseline.'}</p>`:''}</section>`;}
function progress(){const p=P(),range=S().analyticsRange??30,rows=S().sessions.filter(s=>s.status==='completed'&&(range===0||C.daysBetween(s.date,C.dateKey())<range)&&C.daysBetween(s.date,C.dateKey())>=0),first=p.primary==='runner'||p.primary==='hybrid'&&p.hybridPriority==='running'?'running':p.primary==='strength'||p.primary==='hybrid'?'strength':p.primary==='longevity'?'capability':p.primary==='custom'?({power:'plyo',balance:'capability'})[p.customPriority||p.secondary[0]]||p.customPriority||p.secondary[0]||'consistency':'consistency';const runner=root.IXHUA_RUN_UI.progress(range),strength=strengthProgress(rows),cardioRows=rows.filter(s=>s.type==='cardio');return `<div class="ix-progress" data-progress-priority="${first}"><div class="label">${esc(names[p.primary])} / ACTUAL HISTORY</div><h2>See what<br>you’re building<span>.</span></h2><div class="ix-range">${[[7,'1W'],[14,'2W'],[21,'3W'],[30,'1M'],[90,'3M'],[180,'6M'],[365,'1Y'],[0,'ALL']].map(([v,l])=>`<button data-range09="${v}" class="${range===v?'active':''}">${l}</button>`).join('')}</div>${p.primary==='hybrid'?goalCards(p):''}${first==='running'?runner+strength:first==='strength'?strength+(p.primary==='hybrid'||p.secondary.includes('running')?runner:''):first==='capability'?capabilitySummary(p)+strength:`<section data-progress-domain="consistency"><h3>Your rhythm</h3>${metric('COMPLETED',rows.length,'sessions in the selected period')}${p.primary==='custom'?'<p>'+esc(goalLine(p))+'</p>'+metric('FOCUS',rows.filter(s=>s.type===first).length,'completed '+esc(domains[first]||first)+' sessions'):strength}</section>`}${cardioRows.length||(['general','longevity'].includes(p.primary)||p.secondary.includes('cardio'))?`<section data-progress-domain="cardio"><h3>Aerobic consistency</h3><div class="ix-three-metrics">${metric('CARDIO',cardioRows.length,'completed cardio sessions')}${metric('TIME',Math.round(cardioRows.reduce((a,s)=>a+s.elapsedMs/60000,0)),'actual cardio minutes')}</div></section>`:''}<section class="ix-section"><h3>Body-weight history</h3><div class="form-row"><input id="ix-weight-value" class="field" aria-label="Body weight" type="number" min="30" max="700" step="0.1" placeholder="${p.units==='metric'?'kg':'lb'}">${btn('Log weight','weight')}</div>${ctx.chart((S().weightEntries||[]).filter(x=>!range||C.daysBetween(x.date,C.dateKey())<range).map(x=>({date:x.date,value:(+x.weight||+x.n)/(p.units==='metric'?2.2046226218:1)})),'Body weight',p.units==='metric'?'kg':'lb')}</section><section class="ix-section"><h3>Your completed work</h3>${rows.length?rows.slice().reverse().map(s=>`<button class="ix-history-row" data-ix-action="history" data-id="${s.id}"><span>${esc(s.date)} · ${esc(domains[s.type]||s.type)}<b>${esc(s.title)}</b></span><strong>${C.duration(s.elapsedMs/1000)}</strong></button>`).join(''):'<p>No completed sessions in this range. Start from your next planned session.</p>'}</section></div>`;}
function weekly(){const p=P(),rows=S().sessions.filter(s=>s.status==='completed'&&C.daysBetween(s.date,C.dateKey())>=0&&C.daysBetween(s.date,C.dateKey())<7),types=[...new Set([order(p)[0],...(p.primary==='hybrid'?['running','strength']:[]),'running','strength','cardio','mobility','capability','plyo'])].filter(t=>domains[t]&&!['overview','hybrid'].includes(t));ctx.sheet('Your last seven days',`<section data-weekly-priority="${p.primary}"><div class="label">${esc(names[p.primary])} / ACTUAL LOGS</div><h3>${esc(goalLine(p))}</h3>${types.map(type=>{const ss=rows.filter(s=>s.type===type);return `<p><b>${esc(domains[type])}</b> · ${ss.length} completed · ${Math.round(ss.reduce((a,s)=>a+s.elapsedMs/60000,0))} min${type==='strength'?' · '+Math.round(ss.reduce((a,s)=>a+stats(s).volumeKg,0)*(p.units==='metric'?1:2.2046226218))+' '+(p.units==='metric'?'kg':'lb')+' × reps':''}</p>`;}).join('')}<p>${rows.length?'Your next reviewed plan can use these completed sessions.':'No completed sessions yet. Your first saved workout starts this report.'}</p>${btn('Ask about this week','ask')}</section>`);}
function devices(){const p=P();ctx.sheet('Device connections',`<section data-device-priority="${p.primary}"><div class="label">NOT CONNECTED</div><h3>${esc(names[p.primary])} device context</h3><p>Requires Native Device Beta: Apple Watch sessions, Apple Health import, background GPS and device heart-rate collection. No wearable readings are present.</p><p>${['runner','hybrid'].includes(p.primary)?'Running intent: elapsed time, prescribed phase, manually recorded distance and effort. Live pace, GPS and heart rate require device integration.':'Strength / capability intent: the current exercise, completed sets and rest timer. Device-recorded measurements require integration.'}</p><p>Your browser training and manually logged history work without a wearable. Physical-device validation has not been performed.</p></section>`);}
function bind(){if(document.documentElement.dataset.ixAthleteBound)return;document.documentElement.dataset.ixAthleteBound='true';document.addEventListener('click',e=>{const b=e.target.closest('[data-ix-action]');if(!b)return;const a=b.dataset.ixAction;try{if(a==='select-day'){if(ctx.selectDate)ctx.selectDate(b.dataset.date);else{commit(s=>s.selectedDate=b.dataset.date);ctx.render();}}if(a==='ask'){b.closest('dialog')?.close();ctx.ask('athlete',P());}if(a==='weekly')weekly();if(a==='devices')devices();if(a==='open')open(b.dataset.id);if(a==='open-support')supportDetails((S().trainingPlan||[]).find(s=>s.id===b.dataset.id),+b.dataset.supportIndex);if(a==='open-running'){const cardButton=document.createElement('button');cardButton.dataset.ixRun='open';cardButton.dataset.id=b.dataset.id;document.body.append(cardButton);cardButton.click();cardButton.remove();}if(a==='start')start(b.dataset.id);if(a==='start-support')startSupport(b.dataset.id,+b.dataset.supportIndex);if(a==='pause'){commit(s=>C.toggleClock(s.activeSession));ctx.render();}if(a==='rest-toggle'){commit(s=>{const r=s.activeSession?.rest;if(!r)return;const rem=r.paused?r.remaining:Math.max(0,Math.ceil((r.endsAt-Date.now())/1000));r.paused=!r.paused;r.remaining=rem;r.endsAt=r.paused?null:Date.now()+rem*1000;});ctx.render();}if(a==='rest-adjust'){const delta=+b.dataset.seconds||0;commit(s=>{const r=s.activeSession?.rest;if(!r)return;const rem=r.paused?r.remaining:Math.max(0,Math.ceil((r.endsAt-Date.now())/1000));r.remaining=Math.max(0,rem+delta);r.endsAt=r.paused?null:Date.now()+r.remaining*1000;});ctx.render();}if(a==='rest-reset'){commit(s=>{const r=s.activeSession?.rest;if(!r)return;r.paused=true;r.remaining=r.duration;r.endsAt=null;});ctx.render();}if(a==='rest-close'){commit(s=>{if(s.activeSession)s.activeSession.rest=null;});ctx.render();}if(a==='resume')ctx.navigate('training');if(a==='profile')root.IXHUA_ONBOARDING.open();if(a==='food')ctx.food();if(a==='plan')ctx.navigate('plan');if(a==='progress'){b.closest('dialog')?.close();ctx.navigate('progress');}if(a==='exercise')exercise(b.dataset.exercise);if(a==='end')end();if(a==='replace')replace(+b.dataset.index);if(a==='set'){const [i,j]=b.dataset.pair.split(',').map(Number);commit(s=>{if(s.activeSession.status!=='active')throw Error('Resume before logging a set.');const ex=s.activeSession.exercises[i],x=ex.sets[j];if(x.done)x.done=false;else{if(x.reps===''||!Number.isInteger(+x.reps)||+x.reps<1||+x.reps>3600||x.weight===''||!Number.isFinite(+x.weight)||+x.weight<0||+x.weight>1500)throw Error('Enter a valid load and completed reps/time before marking the set.');if(x.rir!==''&&(!Number.isInteger(+x.rir)||+x.rir<0||+x.rir>10))throw Error('Reps in reserve must be 0–10, or left blank.');x.rir=x.rir===''?null:+x.rir;x.weightKg=+x.weight/(s.activeSession.units==='metric'?1:2.2046226218);x.done=true;if(s.autoRest!==false)s.activeSession.rest={duration:ex.restSeconds,remaining:ex.restSeconds,endsAt:Date.now()+ex.restSeconds*1000,paused:false};}});ctx.render();}if(a==='choose-alternative'){const i=+b.dataset.index,ex=E.get(b.dataset.exercise);commit(s=>{const old=s.activeSession.exercises[i],done=old.sets.filter(x=>x.done),pending=old.sets.filter(x=>!x.done);const replacement={...C.clone(ex),plannedSets:pending.length||old.sets.length,sets:(pending.length?pending:old.sets).map(()=>({weight:ex.loadType==='bodyweight'?'0':'',weightKg:ex.loadType==='bodyweight'?0:null,reps:'',rir:'',done:false})),suggestion:T.progression(ex,s.sessions,P()),targetRir:2};if(done.length){old.sets=done;s.activeSession.exercises.splice(i+1,0,replacement);}else s.activeSession.exercises[i]=replacement;});b.closest('dialog').close();ctx.render();}if(a==='extra'){const type=b.dataset.type,p=P(),draft=type==='strength'?T.strength(p,0,S().sessions):type==='mobility'?T.mobility(p):type==='plyo'?T.plyometrics(p,0,S().sessions):type==='capability'?T.capability(p,S().sessions):T.cardio(p);if(!draft.minutes)throw Error(draft.reason);commit(s=>s.extraSessionPreview={...draft,id:C.id(),status:'planned'});open(S().extraSessionPreview.id);}if(a==='history'){const s=S().sessions.find(x=>x.id===b.dataset.id);if(s.type==='running'){const el=document.createElement('button');el.dataset.ixRun='history';el.dataset.id=s.id;document.body.append(el);el.click();el.remove();}else summary(s);}if(a==='weight'){const input=document.getElementById('ix-weight-value'),v=Number(input.value);C.range(v,P().units==='metric'?30:66,P().units==='metric'?320:700,'Body weight');commit(s=>{s.weightEntries=s.weightEntries.filter(x=>x.date!==C.dateKey());s.weightEntries.push({date:C.dateKey(),weight:(v*(P().units==='metric'?2.2046226218:1)).toFixed(1)});});ctx.render();}if(a==='week-back'||a==='week-next'){commit(s=>{const current=s.planWeek||s.trainingPlan?.find(x=>x.date>=C.dateKey())?.week||C.monday(C.dateKey());s.planWeek=C.addDays(current,a==='week-back'?-21:21);});ctx.render();}if(a==='event')eventForm();if(a==='personalize-week')personalizeWeek();if(a==='replan')reviewPlan();if(a==='remove-event')reviewPlan(null,{index:+b.dataset.index});if(a==='library'){ctx.sheet('IXHUA exercise library',`<input class="field" id="ix-library-search" placeholder="Search 73 exercises" aria-label="Search exercise library"><div id="ix-library-list">${E.library.map(e=>`<button class="ix-alternative" data-ix-action="exercise" data-exercise="${e.id}"><strong>${esc(e.name)}</strong><span>${esc(e.primary)} · ${esc(e.equipment)}</span></button>`).join('')}</div>`);document.getElementById('ix-library-search').oninput=e=>{document.querySelectorAll('#ix-library-list button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));};}if(a==='export-session')ctx.download(S().sessions.find(s=>s.id===b.dataset.id),'IXHUA-workout-summary.json');}catch(error){ctx.notify(error.message);}});const update=e=>{const input=e.target;if(input.matches('[data-ix-set]')){const [i,j,k]=input.dataset.ixSet.split(',');try{commit(s=>{const x=s.activeSession.exercises[+i].sets[+j];x[k]=input.value;x.done=false;if(k==='weight')x.weightKg=input.value===''?null:+input.value/(s.activeSession.units==='metric'?1:2.2046226218);});input.closest('.ix-set-row')?.classList.remove('is-done');const done=input.closest('.ix-set-row')?.querySelector('[data-ix-action="set"]');if(done){done.setAttribute('aria-pressed','false');done.textContent='○';}}catch(error){ctx.notify(error.message);}}if(input.matches('[data-ix-metric]')){try{const k=input.dataset.ixMetric;let v=input.type==='checkbox'?input.checked:input.tagName==='SELECT'?input.value:input.value===''?null:Number(input.value);if(k==='rpe'&&v!=null)C.range(v,1,10,'Effort');if(k==='distanceKm'&&v!=null){C.range(v,0,500,'Distance');v*=S().activeSession.units==='metric'?1:1.609344;}commit(s=>s.activeSession.metrics[k]=v);}catch(error){ctx.notify(error.message);}}if(input.matches('[data-ix-session-notes]'))commit(s=>s.activeSession.notes=input.value);};document.addEventListener('input',update);document.addEventListener('change',e=>{if(e.target.tagName==='SELECT')update(e);});setInterval(()=>{const el=document.getElementById('ix-session-elapsed');if(el&&S().activeSession)el.textContent=C.duration(C.elapsed(S().activeSession)/1000);const rest=document.getElementById('ix-rest-live'),r=S().activeSession?.rest;if(rest&&r)rest.textContent=C.duration(restRemaining(r));},500);}
root.IXHUA_ATHLETE_UI={init,order,today,training,progress,plan,bind,stats,summary,card,personalizeWeek,compactDate};
})(window);
